 const title:Row={account:'Account',position:'Holding',transaction:'Investment transaction',deposit:'Fixed deposit',asset:'Personal asset',card:'Credit card',income:'Income receipt',payment:'Card payment',watch:'Watchlist investment',prices:'Dated prices'};
 async function submit(e:React.FormEvent){e.preventDefault();if(submitting.current)return;submitting.current=true;setBusy(true);setErr('');try{if(kind==='prices'){const rows=data.rows.trim().split('\n').map((line:string)=>{const [date,price]=line.split(',').map(s=>s.trim());return {date,price};});await api('/prices','POST',{key:data.key,rows});}else{const body={...data};if(kind==='position')body.tags=data.tags.split(',').map((s:string)=>s.trim()).filter(Boolean);await api(`/records/${kind}${data.id?'/'+data.id:''}`,data.id?'PUT':'POST',body,data.id?undefined:submitKey.current);}saved();}catch(e:any){setErr(e.message);}finally{submitting.current=false;setBusy(false);}}
 return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)closeSafely();}}><section ref={focusRef} className="modal" role="dialog" aria-modal="true" aria-labelledby="entry-title"><div className="modal-head"><div><h2 id="entry-title">{data.id?'Edit':'Add'} {title[kind].toLowerCase()}</h2><p>Saved only to your local ledger.</p></div><button aria-label="Close form" disabled={busy} onClick={closeSafely}><X size={21}/></button></div><form onSubmit={submit}>{discard&&<div className="discard-prompt" role="alert"><strong>Discard unsaved changes?</strong><p>Your edits have not been saved.</p><div><button type="button" className="button" onClick={()=>setDiscard(false)}>Keep editing</button><button type="button" className="button" onClick={close}>Discard changes</button></div></div>}{err&&<div className="notice error" role="alert">{err}</div>}{['position','watch'].includes(kind)&&data.provider!=='manual'&&<div className="instrument-search"><p>Enter the investment name below, then find and select the exact exchange symbol or fund scheme.</p><button type="button" className="button" disabled={finding||data.name.trim().length<2} onClick={findInvestment}>{finding?'Finding…':'Find investment'}</button>{lookupMessage&&<p role="status">{lookupMessage}</p>}<div className="lookup-results">{lookup.map(r=><button className="button" type="button" key={r.symbol} onClick={()=>{setData({...data,name:r.name,symbol:r.symbol,category:r.provider==='mfapi'?'mutual_fund':data.category});setLookup([]);setLookupMessage('Selected '+r.symbol);}}>{r.name} · {r.symbol} · {r.exchange}</button>)}</div></div>}{kind==='card'&&<p className="notice neutral">Benefits and published rates are checked automatically. Enter the payment due date from your actual statement.</p>}{kind==='asset'&&<p className="notice neutral">Use the exact model and capacity. Public listing links and available prices will appear automatically after saving.</p>}<div className="form-grid">{fields[kind].map(f=><label key={f.key} className={(f.type==='textarea'||f.type==='checkbox'||f.key==='tags'||f.key==='symbol'?'full ':'')+(f.type==='checkbox'?'check-label':'')}>{f.type!=='checkbox'&&<span>{f.label}</span>}{f.type==='select'?<select aria-label={f.label} value={data[f.key]} onChange={e=>setData({...data,[f.key]:e.target.value})}>{f.options?.map(([value,label],i)=><option key={value+i} value={value}>{label}</option>)}</select>:f.type==='textarea'?<textarea aria-label={f.label} rows={4} value={data[f.key]} onChange={e=>setData({...data,[f.key]:e.target.value})}/>:f.type==='checkbox'?<><input type="checkbox" checked={data[f.key]} onChange={e=>setData({...data,[f.key]:e.target.checked})}/><span>{f.label}</span></>:<input aria-label={f.label} onInput={e=>{if(f.type==='date'){const value=e.currentTarget.value;setData(prior=>({...prior,[f.key]:value}));}}} onBlur={e=>{if(f.type==='date'){const value=e.currentTarget.value;setData(prior=>({...prior,[f.key]:value}));}}} type={f.type} step={f.type==='number'?'any':undefined} min={f.type==='number'?'0':undefined} value={data[f.key]??''} onChange={e=>setData({...data,[f.key]:e.target.value})}/>} {f.hint&&<small>{f.hint}</small>}</label>)}</div><div className="modal-foot"><button type="button" className="button" disabled={busy} onClick={closeSafely}>Cancel</button><button type="submit" className="button primary" disabled={busy}>{busy?'Saving…':'Save '+title[kind].toLowerCase()}</button></div></form></section></div>;
